class NotificationChecker{constructor(){this.checkInterval=3e5,this.subscribers=[],this.notifications=[],this.lastCheck=null}async init(){try{const t=await fetch("https://backup0821.github.io/API/Better-vegetable-catcher/subscribe.json"),e=await t.json();this.subscribers=e.subscribers;const i=await fetch("https://backup0821.github.io/API/Better-vegetable-catcher/notifications.json"),o=await i.json();this.notifications=o.notifications,this.startChecking()}catch(t){console.error("初始化通知檢查器時發生錯誤:",t)}}startChecking(){setInterval(()=>this.checkNotifications(),this.checkInterval),this.checkNotifications()}async checkNotifications(){try{const t=new Date,e=this.notifications.filter(e=>{const i=new Date(e.startTime),o=new Date(e.endTime);return t>=i&&t<=o});e.length>0&&await this.sendNotifications(e),this.lastCheck=t}catch(t){console.error("檢查通知時發生錯誤:",t)}}async sendNotifications(t){for(const e of this.subscribers)for(const i of t)if(this.shouldSendToDevice(i,e.deviceId))try{await this.sendNotification(e.subscription,i)}catch(t){console.error("發送通知時發生錯誤:",t)}}shouldSendToDevice(t,e){return t.public||t.targetDevices.includes("everyone")||t.targetDevices.includes(e)}async sendNotification(t,e){if(!(await fetch(t.endpoint,{method:"POST",headers:{"Content-Type":"application/json",Authorization:"key=YOUR_SERVER_KEY"},body:JSON.stringify({title:e.title,body:e.message,icon:"/Better-vegetable-catcher/WEB/image/png/icon-192.png",data:{url:"/Better-vegetable-catcher/WEB/",notificationId:e.id}})})).ok)throw new Error("發送通知失敗")}}class NotificationTester{constructor(){this.checker=new NotificationChecker}async testSubscription(){try{if("granted"===await Notification.requestPermission()){console.log("✅ 通知權限已授予");const t=await navigator.serviceWorker.register("/Better-vegetable-catcher/WEB/service-worker.js");console.log("✅ Service Worker 已註冊");const e=await t.pushManager.subscribe({userVisibleOnly:!0,applicationServerKey:urlBase64ToUint8Array("BO-QjkYMehAHI8suojRy1dBmOsrn0dwtgwt7rL4gWz_SbUqtN84VxcNiUn44xWRUAi7gmC-b9_MsbZfolV6UKuw")});return console.log("✅ 推播訂閱成功"),localStorage.setItem("pushSubscription",JSON.stringify(e)),console.log("✅ 訂閱資訊已儲存"),await this.sendTestNotification(e),!0}return console.log("❌ 通知權限被拒絕"),!1}catch(t){return console.error("❌ 測試訂閱時發生錯誤:",t),!1}}async sendTestNotification(t){try{if(!(await fetch(t.endpoint,{method:"POST",headers:{"Content-Type":"application/json",Authorization:"key=YOUR_SERVER_KEY"},body:JSON.stringify({title:"測試通知",body:"這是一則測試通知，用於驗證推播功能是否正常運作",icon:"/Better-vegetable-catcher/WEB/image/png/icon-192.png",data:{url:"/Better-vegetable-catcher/WEB/",notificationId:"test-notification"}})})).ok)throw new Error("發送測試通知失敗");console.log("✅ 測試通知已發送")}catch(t){console.error("❌ 發送測試通知時發生錯誤:",t)}}async testNotificationCheck(){try{return await this.checker.init(),console.log("✅ 通知檢查器已初始化"),await this.checker.checkNotifications(),console.log("✅ 通知檢查已完成"),!0}catch(t){return console.error("❌ 測試通知檢查時發生錯誤:",t),!1}}}const tester=new NotificationTester;window.addEventListener("load",async()=>{console.log("開始測試推播通知系統...");const t=await tester.testSubscription();console.log("訂閱測試結果:",t?"成功":"失敗");const e=await tester.testNotificationCheck();console.log("通知檢查測試結果:",e?"成功":"失敗")});const checker=new NotificationChecker;checker.init();